import{_ as t,c as r,j as e,a as o,o as s}from"./chunks/framework.CqbvlPrP.js";const C=JSON.parse('{"title":"为啥有那么多愿意大篇幅分享自己炒股经验的人？","description":"","frontmatter":{},"headers":[],"relativePath":"stock/交易认知/分享交易认知-实现PDCA.md","filePath":"stock/交易认知/分享交易认知-实现PDCA.md"}'),n={name:"stock/交易认知/分享交易认知-实现PDCA.md"};function l(c,a,_,d,p,i){return s(),r("div",null,a[0]||(a[0]=[e("h1",{id:"为啥有那么多愿意大篇幅分享自己炒股经验的人",tabindex:"-1"},[o("为啥有那么多愿意大篇幅分享自己炒股经验的人？ "),e("a",{class:"header-anchor",href:"#为啥有那么多愿意大篇幅分享自己炒股经验的人","aria-label":'Permalink to "为啥有那么多愿意大篇幅分享自己炒股经验的人？"'},"​")],-1),e("p",null,"在质量管理中有一个常用的方法，就是PDCA循环，也叫戴明环。他的主要内容就是:P (计划 PLAN) :确定目标制定计划；D (实施 DO) :实施计划，记录过程；C (检查 CHECK) :评估结果，识别问题；A（ACTION，处理）:改进总结提高，做的好的地方保留复制推广，做的不好的地方进入下一个PDCA循环。这种方法不但用在质量管理中，在所有的事情中都可以借鉴和应用。",-1),e("p",null,"人对事物的认知深度都是渐变的，包括交易。回到你的问题，你看到的所谓分享，很可能只是某一个人某一段时间对市场的认知总结(那些故弄玄虚或者钓鱼的人除外)，属于阶段性的认知，这些认知有的是正确的，有些是错误的，有些是片面的碎片化的，不过都属于PDCA中D的实施之后的总结过程。这种总结无论是不是处于分享的目的，对于个人的改进提高都是有好处的，是必要的，是对于前面工作一个阶段性的总结梳理，也是为后面的努力指出方向，如果你想在交易这一行走的更远更久，取得成绩，这种总结分析过程必不可少。当然认知不同，这个总结有好有坏，水平有高有低，有营养也有糟粕，需要你能有一双慧眼能分辨和取舍。",-1),e("p",null,"交易发展到现在将近400年，没有什么了不得的秘密可言，核心理念的东西该说的那些经典的书籍都讲的很透彻了，最多会有一些交易技巧，交易模式的变化，你看到的那些所谓的手绘的图表其实就是一些碎片化的是是而非的模块，但是这些东西都不是盈利的核心问题，交易也不是比你哪方面知道的多，交易是木桶效应，短板决定收益，认知、性格、计划、执行……你哪方面有短板，就会在哪里犯错，钱就会从哪流走。所以交易的总结最重要的并不是我通过交易总结到了哪些圣杯，而是通过评估，你发现自己还有哪些问题，这样才会进入下一个PDCA循环，从而让你的短板越来越高，你留下的水（财），才可能越来越多。",-1),e("p",null,"所以交易是个很个性化的事情，你所谓的发现了交易的经验要不要密不示人，其实并不重要，资本市场几百年，交易类的书籍不说浩如烟海，汗牛充栋总是有的，多少绝顶聪明的人参与其中，取得耀眼的业绩，分享了自己体会经验，从理念到技术，从心理到经历，应有尽有，这里面有开宗立派的宗师，也有富可敌国人物。真不差知乎上多几个少几个还在摸索阶段的股民的心得体会，把眼光从知乎跳出去，这里并不是一个专业的投资论坛，虽然有一些分享还不错，但是不是说这里水平高的不得了。每个人的短板问题都不一样，需要改进的方向和解决的问题也不一样，也不存在普适真谛或者圣杯，甚至你以为好的不得了的经验，实际用的时候汝之蜜糖，彼之砒霜都是常见的事情。",-1)]))}const D=t(n,[["render",l]]);export{C as __pageData,D as default};
